  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Coptisine, a protoberberine isoquinoline alkaloid, was detected in mouse brain homogenates by LC-MS/MS, demonstrating that this alkaloid class crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Palmatine, another protoberberine alkaloid, was detected in rat CSF after administration, directly showing BBB passage for a close structural relative of the query.",
